import{_ as e,o as n,c as i,a2 as r}from"./chunks/framework.CCtxZRER.js";const g=JSON.parse('{"title":"SOP Write Off & Barang Rusak","description":"Mengenali, memisahkan, dan melaporkan barang write off serta barang rusak atau kedaluwarsa.","frontmatter":{"title":"SOP Write Off & Barang Rusak","description":"Mengenali, memisahkan, dan melaporkan barang write off serta barang rusak atau kedaluwarsa.","status":"draf","dasar":"penyebab barang write off dari materi Gudang Teknik dan praktik umum pergudangan","nomor_dokumen":null,"versi":0.1,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik"],"kata_kunci":["SOP","write off","dead stock","barang rusak","kedaluwarsa","expired","overstock","karantina","penghapusan"]},"headers":[],"relativePath":"sop/dead-stock.md","filePath":"sop/dead-stock.md"}'),t={name:"sop/dead-stock.md"};function l(u,a,s,k,d,o){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="sop-write-off-barang-rusak" tabindex="-1">SOP Write Off &amp; Barang Rusak <a class="header-anchor" href="#sop-write-off-barang-rusak" aria-label="Permalink to &quot;SOP Write Off &amp; Barang Rusak&quot;">​</a></h1><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Mencegah barang yang tidak terpakai, rusak, atau kedaluwarsa tercampur dengan stok layak pakai, dan memastikan barang tersebut ditindaklanjuti oleh pihak yang berwenang.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Berlaku untuk barang yang ditemukan rusak, kedaluwarsa, tidak sesuai spesifikasi, atau lama tidak bergerak. Keputusan penghapusan, penjualan, atau pemusnahan <strong>bukan</strong> wewenang peserta magang.</p><h2 id="sebelum-mulai" tabindex="-1">Sebelum mulai <a class="header-anchor" href="#sebelum-mulai" aria-label="Permalink to &quot;Sebelum mulai&quot;">​</a></h2><ul><li>Memahami penyebab barang write off di <a href="/WareHouse/divisi/manajemen-inventory#write-off">Manajemen Inventory</a>.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li>Kenali tanda-tandanya: barang rusak, melewati tanggal kedaluwarsa, untuk mesin yang sudah tidak dipakai, atau lama tidak ada permintaan.</li><li>Pisahkan barang ke area yang ditentukan dan beri tanda yang jelas, misalnya &quot;Tidak untuk dikeluarkan&quot;.</li><li>Catat kode, nama, jumlah, kondisi, lokasi asal, dan perkiraan penyebabnya.</li><li>Laporkan daftar tersebut ke pembimbing.</li><li>Ikuti keputusan pihak yang berwenang. Perbarui catatan stok hanya setelah ada persetujuan.</li></ol><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Barang sudah dipisahkan dan diberi tanda.</li><li>Data barang dan penyebabnya sudah dicatat.</li><li>Laporan sudah diserahkan ke pembimbing.</li><li>Catatan stok belum diubah sebelum ada persetujuan.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Barang rusak bisa berbahaya</p><ul><li>Consumable yang bocor atau kedaluwarsa, seperti oli, grease, dan sealant, ditangani dengan sarung tangan dan tidak dibuang sembarangan. Ikuti aturan limbah perusahaan.</li><li>Barang tajam atau pecah dibungkus agar tidak melukai orang lain.</li></ul></div><h2 id="pencegahan" tabindex="-1">Pencegahan <a class="header-anchor" href="#pencegahan" aria-label="Permalink to &quot;Pencegahan&quot;">​</a></h2><ul><li>Jalankan FIFO dengan disiplin.</li><li>Cek posisi stok sebenarnya sebelum mengajukan pembelian.</li><li>Laporkan jika mesin yang dilayani sudah tidak dipakai atau sudah dimodifikasi, agar suku cadangnya dievaluasi.</li></ul>',15)])])}const m=e(t,[["render",l]]);export{g as __pageData,m as default};
